code_blocks.code:
import json
import re
import datetime
try:
    vars['route'] = 'boundary'
    months = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    units = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    tens = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
    currencies = [('TL', 'Türk Lirası'), ('USD', 'Dolar'), ('EUR', 'Euro'), ('GBP', 'İngiliz Sterlini')]
    names = dict(currencies)
    ordinals = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
    today = datetime.datetime.fromisoformat(str(vars.get('now') or '').replace('Z', '+00:00')).date()
    def clone(value):
        return json.loads(json.dumps(value))
    def norm(value):
        return re.sub(r'\s+', ' ', str(value or '').replace('İ', 'i').replace('I', 'ı').lower()).strip()
    def clean(value):
        return re.sub(r'[\x00-\x1f]', ' ', str(value or ''))
    def num(n):
        n = int(n)
        if n == 0:
            return 'sıfır'
        if n < 0:
            return 'eksi ' + num(-n)
        if n >= 1000000000000000:
            raise ValueError('amount magnitude')
        parts = []
        for scale, label in [(1000000000000, 'trilyon'), (1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')]:
            if n >= scale:
                q, n = divmod(n, scale)
                parts.append(('' if scale == 1000 and q == 1 else num(q) + ' ') + label)
        if n >= 100:
            q, n = divmod(n, 100)
            parts.append(('' if q == 1 else units[q] + ' ') + 'yüz')
        if n >= 10:
            q, n = divmod(n, 10)
            parts.append(tens[q])
        if n:
            parts.append(units[n])
        return ' '.join(parts)
    def amount(value, currency):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError('amount absent')
        s = str(value)
        if 'e' in s.lower():
            raise ValueError('exact decimal required')
        negative = s.startswith('-')
        s = s.lstrip('-')
        a = s.split('.')
        fraction = a[1] if len(a) > 1 else ''
        if len(fraction) > 2 and any(x != '0' for x in fraction[2:]):
            raise ValueError('cannot round amount')
        minor = int((fraction + '00')[:2])
        text = num(int(a[0])) + ' ' + names[currency]
        if minor:
            text += ' ' + num(minor) + ' ' + ('kuruş' if currency == 'TL' else 'peni' if currency == 'GBP' else 'sent')
        return ('eksi ' if negative else '') + text
    def date(value):
        if not isinstance(value, str) or not re.fullmatch(r'[0-9]{2}\.[0-9]{2}\.[0-9]{4}', value):
            raise ValueError('date absent')
        return datetime.datetime.strptime(value, '%d.%m.%Y').date()
    def spoken_date(value):
        d = date(value)
        return str(d.day) + ' ' + months[d.month] + ' ' + str(d.year)
    def digit_speech(value):
        if not re.fullmatch(r'[0-9]{4}', str(value or '')):
            raise ValueError('last four absent')
        return ' '.join(units[int(x)] for x in value)
    def intro(card):
        name = clean(card.get('productName'))
        return 'Sonu ' + digit_speech(card.get('cardNumberLast4')) + ' ile biten ' + (name + ' ' if name else '') + 'kartınız'
    def join_names(items):
        return items[0] if len(items) == 1 else ', '.join(items[:-1]) + ' ve ' + items[-1]
    def ask(stage, text, short='', key=''):
        key = key or stage
        if vars.get('question_key') != key:
            vars['attempts'] = 0
            vars['silences'] = 0
        vars['question_key'] = key
        vars['stage'] = stage
        vars['say'] = text
        vars['last_question'] = text
        vars['short_question'] = short or text
        vars['route'] = 'listen'
    def finish(kind, text):
        vars['boundary_intent'] = kind
        vars['say'] = text
        vars['route'] = 'boundary'
        vars['email_consent'] = 'none'
        vars['week_consent'] = 'none'
    def menu(prefix=''):
        finish('main_menu', prefix + 'Sizi ana menüye yönlendiriyorum.')
    def failure(week=False, uncertain=False):
        text = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if week else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
        if uncertain:
            text = ('Değişikliğin tamamlanıp tamamlanmadığını doğrulayamıyorum. ' if week else 'Gönderimin tamamlanıp tamamlanmadığını doğrulayamıyorum. ') + text
        finish('agent', text)
    def fail_try(text):
        vars['attempts'] = int(vars.get('attempts', 0)) + 1
        vars['last_unproductive_question'] = text
        if vars['attempts'] >= 3:
            finish('main_menu', 'Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.')
        else:
            vars['say'] = text
            vars['last_question'] = text
            vars['short_question'] = text
            vars['route'] = 'listen'
    def queue(op):
        routes = dict(cards_balance='load_balance', contact_email_get='load_contact', statement_week_get='load_week', statement_week_decide='preview_week', statement_week_change='change_week', statement_pdf_send='send_pdf')
        vars['pending_api'] = op
        vars['api_response'] = dict()
        vars['api_event'] = ''
        vars['route'] = routes[op]
    def eligible():
        return [c for c in vars.get('cards', []) if c.get('isMainCard') is True and c.get('status') == 'A']
    def selection(prefix='', fresh=False):
        cards = eligible()
        if not cards:
            finish('main_menu', 'Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
            return
        opts = list(dict.fromkeys(clean(c.get('productName')) for c in cards if c.get('productName')))
        text = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
        if opts:
            text += ' Örneğin, ' + ' veya '.join(opts[:2]) + ' diyebilirsiniz.'
        vars['candidates'] = clone(cards)
        if fresh:
            vars['question_key'] = ''
        ask('selection', prefix + text, 'Hangi kartınızı seçmek istersiniz?')
    def select(card):
        vars['selected_card'] = clone(card)
        vars['selected_card_number'] = card['cardNumber']
        vars['email_consent'] = 'none'
        vars['week_consent'] = 'none'
        vars['send_currency'] = ''
        vars['issued_statement_date'] = ''
        vars['balance_data'] = dict()
        vars['balance_card'] = ''
        vars['week_data'] = dict()
        vars['week_card'] = ''
        vars['preview_data'] = dict()
        vars['preview_key'] = ''
        if vars.get('followup') == 'week':
            vars['followup'] = ''
            start_week()
        else:
            queue('cards_balance')
    def known_used():
        number = vars.get('selected_card_number')
        changed = vars.get('changed_years', dict())
        w = vars.get('week_data', dict()) if vars.get('week_card') == number else dict()
        related = w.get('relatedCardNumber') if w.get('relationType') in ('M', 'C') else ''
        return changed.get(number) == today.year or bool(related and changed.get(related) == today.year)
    def start_week():
        vars['week_explicit'] = 'yes'
        if not vars.get('selected_card_number'):
            vars['followup'] = 'week'
            selection()
        elif known_used():
            menu('Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Bu yıl değişiklik yapıldığı için tekrar değiştiremiyorum. ')
        elif vars.get('selected_card_number') in vars.get('uncertain_changes', []):
            failure(True, True)
        else:
            queue('statement_week_get')
    def offer(prefix=''):
        if vars.get('no_statement_debt') == 'yes':
            menu(prefix)
        else:
            vars['reading_prefix'] = prefix
            queue('contact_email_get')
    def after_reading(text):
        vars['last_reading'] = text
        seen = list(vars.get('seen_cards', []))
        number = vars.get('selected_card_number')
        if number not in seen:
            seen.append(number)
        vars['seen_cards'] = seen
        others = [c for c in eligible() if c.get('cardNumber') not in seen]
        if vars.get('email_requested') == 'yes':
            vars['reading_prefix'] = text + ' '
            queue('contact_email_get')
        elif vars.get('wanted') in ('due', 'minimum'):
            offer(text + ' ')
        elif others:
            ask('another', text + ' Başka bir kartınızın borcunu öğrenmek ister misiniz?', 'Başka bir kartınızın borcunu öğrenmek ister misiniz?', 'another:' + str(number))
        else:
            offer(text + ' ')
    def email_setup(prefix=''):
        vars['email_consent'] = 'none'
        if int(vars.get('send_attempts', 0)) >= 3:
            menu(prefix)
            return
        if not vars.get('registered_email'):
            menu(prefix + 'Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum. ')
            return
        if vars.get('balance_card') != vars.get('selected_card_number'):
            vars['email_requested'] = 'yes'
            queue('cards_balance')
            return
        issued = vars.get('balance_data', dict()).get('statementDate')
        if not issued:
            menu(prefix + 'Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstrenizi gönderemiyorum. ')
            return
        date(issued)
        vars['issued_statement_date'] = issued
        currency = vars.get('send_currency') or vars.get('wanted_currency')
        if currency not in names:
            ask('email_currency', prefix + 'Ekstrenizi hangi para birimi için göndermemi istersiniz: Türk Lirası, Dolar, Euro veya İngiliz Sterlini?', 'Hangi para birimindeki ekstrenizi istersiniz?')
            return
        vars['send_currency'] = currency
        address = str(vars['registered_email'])
        spoken = address
        if len(address) > 40 or re.search(r'[^A-Za-z0-9@._+\-]', address):
            local, sep, domain = address.partition('@')
            spoken = clean(local[:1]) + ' ile başlayan ' + clean(domain) + ' adresiniz' if sep and local and domain else 'bankamızda kayıtlı e-posta adresiniz'
        key = json.dumps([vars.get('selected_card_number'), issued, currency, address], ensure_ascii=False)
        vars['email_confirm_key'] = key
        ask('email_confirm', prefix + spoken_date(issued) + ' tarihli ' + names[currency] + ' ekstrenizi ' + clean(spoken) + ' adresine göndermemi ister misiniz?', 'Belirtilen ekstrenizi kayıtlı adresinize göndermemi onaylıyor musunuz?', 'email:' + key + ':' + str(vars.get('send_attempts', 0)))
    def week_key():
        w = vars.get('week_data', dict())
        p = vars.get('preview_data', dict())
        return json.dumps([vars.get('selected_card_number'), int(vars.get('requested_week')), w.get('statementDay'), p.get('statementDate'), p.get('statementDueDate'), w.get('relationType'), w.get('relatedCardNumber'), w.get('relatedCardProductName')], ensure_ascii=False)
    def week_options():
        current = vars['week_data']['statementWeek']
        options = [ordinals[w] for w in (1, 2, 3, 4) if w != current]
        text = 'Hesap kesim tarihinizi ayın ' + ', '.join(options[:-1]) + ' ya da ' + options[-1] + ' haftasına alabilirim. Hangisini tercih edersiniz?'
        ask('week_choice', text, text, 'week_choice:' + str(vars.get('selected_card_number')))
    def preview_confirmation(prefix=''):
        w = vars['week_data']
        p = vars['preview_data']
        relation = w.get('relationType')
        text = prefix
        if relation == 'M':
            text += 'Bu değişiklik kartınıza bağlı ' + clean(w.get('relatedCardProductName')) + ' kartınızı da etkileyecek. '
        elif relation == 'C':
            text += 'Bu değişiklik kartınızın bağlı olduğu ' + clean(w.get('relatedCardProductName')) + ' kartınızı da etkileyecek. '
        text += 'Yeni hesap kesim haftanız her ayın ' + ordinals[int(vars['requested_week'])] + ' haftası olacak. Yeni hesap kesim tarihiniz ' + spoken_date(p['statementDate']) + ', son ödeme tarihiniz ' + spoken_date(p['statementDueDate']) + ' olacak. Onaylıyor musunuz?'
        vars['week_confirm_key'] = week_key()
        ask('week_confirm', text, 'Belirtilen yeni tarihleri ve varsa diğer kartınıza etkisini onaylıyor musunuz?', 'confirm:' + vars['week_confirm_key'])
    def reading(d):
        opening = intro(vars['selected_card'])
        issued = d.get('statementDate')
        due = d.get('lastPayDate')
        next_cut = d.get('nextStatementDate')
        vars['no_statement_debt'] = 'yes' if d.get('statementPaymentStatus') == 'NO_DEBT' or not issued else 'no'
        blocks = [(c, n, d.get('debt' + c)) for c, n in currencies if isinstance(d.get('debt' + c), dict) and d.get('debt' + c)]
        wanted = vars.get('wanted', 'all')
        currency = vars.get('wanted_currency')
        if wanted == 'due':
            return 'Borçlarınız için son ödeme tarihiniz bugündür.' if due and date(due) == today else 'Borçlarınız için son ödeme tarihiniz ' + spoken_date(due) + '.' if due else 'Henüz kesilmiş bir ekstreye ait son ödeme tarihi bulunmuyor.'
        if wanted == 'minimum':
            chosen = [(c, n, b) for c, n, b in blocks if not currency or c == currency]
            return opening + ' için ' + ' '.join(n + ' minimum ödeme tutarınız ' + amount(b['minPayment'], c) + '.' for c, n, b in chosen) if chosen else 'İstediğiniz para birimine ait minimum ödeme bilgisi bulunmuyor.'
        cut_today = any(s and date(s) == today for s in (issued, next_cut))
        past_due = bool(due and date(due) < today)
        if cut_today or (issued and past_due) or wanted == 'total':
            text = opening + ' için '
            if cut_today:
                text += 'hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. '
            elif past_due:
                text += 'son ödeme tarihiniz geçmiştir. '
            clear = []
            lines = []
            for c, n, b in blocks:
                if b['totalDebt'] > 0:
                    lines.append(n + ' toplam borcunuz ' + amount(b['totalDebt'], c) + '.')
                else:
                    clear.append(n)
            text += ' '.join(lines)
            if clear:
                text += ' ' + join_names(clear) + ' borcunuz bulunmamaktadır.'
            tl = d.get('debtTL')
            if past_due and d.get('automaticPaymentFlag') == 'Y' and isinstance(tl, dict) and tl.get('remainAutomaticPaymentAmount', 0) > 0:
                text += ' Otomatik ödemenizden henüz alınacak tutar ' + amount(tl['remainAutomaticPaymentAmount'], 'TL') + '.'
            if due:
                text += ' Borçlarınız için son ödeme tarihiniz ' + ('bugündür.' if date(due) == today else spoken_date(due) + '.')
            return text
        if not issued:
            text = opening + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
            if next_cut:
                text += ' İlk hesap kesim tarihiniz ' + spoken_date(next_cut) + ' olacak.'
            return text
        if d.get('statementPaymentStatus') == 'NO_DEBT':
            text = opening + 'ın ' + spoken_date(issued) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
            tl = d.get('debtTL')
            if isinstance(tl, dict) and 'totalDebt' in tl:
                if tl['totalDebt'] >= 0:
                    text += ' Gelecek dönemler dahil toplam borcunuz ' + amount(tl['totalDebt'], 'TL') + '.'
                else:
                    text += ' Türk Lirası alacak bakiyeniz ' + amount(-tl['totalDebt'], 'TL') + '.'
            if due:
                text += ' Son ödeme tarihiniz ' + ('bugündür.' if date(due) == today else spoken_date(due) + ' olacaktır.')
            return text
        lines = []
        clear = []
        for c, n, b in blocks:
            if b['remainingDebt'] <= 0:
                clear.append(n)
            elif c != 'TL':
                lines.append(n + ' borcunuz ' + amount(b['statementDebt'], c) + ', kalan toplam borcunuz ' + amount(b['remainingDebt'], c) + ', ödenmesi gereken minimum tutar ' + amount(b['minPayment'], c) + '.')
            elif b['remainingMinPayment'] <= 0:
                lines.append(n + ' borcunuz ' + amount(b['statementDebt'], c) + ', kalan toplam borcunuz ' + amount(b['remainingDebt'], c) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            elif b['remainingMinPayment'] >= b['minPayment']:
                lines.append(n + ' borcunuz ' + amount(b['statementDebt'], c) + ', ödenmesi gereken minimum tutar ' + amount(b['minPayment'], c) + '.')
            else:
                lines.append(n + ' borcunuz ' + amount(b['statementDebt'], c) + ', ödenmesi gereken minimum tutar ' + amount(b['minPayment'], c) + ', kalan toplam borcunuz ' + amount(b['remainingDebt'], c) + ', kalan minimum ödeme tutarınız ' + amount(b['remainingMinPayment'], c) + '.')
        text = opening + 'a ait ' + spoken_date(issued) + ' tarihinde kesilen ekstre ' + ' '.join(lines)
        if lines and clear:
            text += ' ' + join_names(clear) + ' borcunuz bulunmamaktadır.'
        if not lines:
            text = opening + 'ın ' + spoken_date(issued) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        if due:
            text += ' Borçlarınız için son ödeme tarihiniz ' + ('bugündür.' if date(due) == today else spoken_date(due) + '.')
        return text
    pending = str(vars.get('pending_api') or '')
    if pending:
        vars['pending_api'] = ''
        envelope = vars.get('api_response', dict())
        envelope = envelope if isinstance(envelope, dict) else dict()
        body = envelope.get('data')
        body = body if isinstance(body, dict) else dict()
        result_body = body.get('result')
        result_body = result_body if isinstance(result_body, dict) else dict()
        data = body.get('data')
        status = str(envelope.get('status_code', ''))
        code = result_body.get('returnCode')
        good = status == '200' and code == '1' and result_body.get('code') == code and isinstance(data, dict) and vars.get('api_guard') == 'allowed' and vars.get('api_event') == pending
        week_op = pending in ('statement_week_get', 'statement_week_decide', 'statement_week_change')
        write = pending in ('statement_pdf_send', 'statement_week_change')
        if pending == 'cards_list' and status == '404' and code == 'FB_IVR_CHANNEL_102' and vars.get('api_guard') == 'allowed':
            finish('main_menu', 'Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
        elif not good:
            definite = status in ('400', '404') and code in ('INVALID_ARGUMENTS_ERROR', 'FB_IVR_CHANNEL_107')
            if write and definite:
                vars['write_outcome'] = 'rejected'
            failure(week_op, write and not definite and vars.get('write_outcome') == 'unknown')
        elif pending == 'cards_list':
            cards = data.get('cards')
            if not isinstance(cards, list) or any(not isinstance(c, dict) or not isinstance(c.get('cardNumber'), str) or not re.fullmatch(r'[0-9]{4}', str(c.get('cardNumberLast4') or '')) for c in cards):
                raise ValueError('cards shape')
            vars['cards'] = clone(cards)
            public = [dict(productName=clean(c.get('productName')), cardNumberLast4=c.get('cardNumberLast4'), isMainCard=c.get('isMainCard')) for c in cards]
            vars['public_cards'] = json.dumps(public, ensure_ascii=False)
            usable = eligible()
            if not usable:
                finish('main_menu', 'Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
            elif len(usable) == 1:
                select(usable[0])
            else:
                selection()
        elif pending == 'cards_balance':
            vars['balance_data'] = clone(data)
            vars['balance_card'] = vars.get('selected_card_number')
            after_reading(reading(data))
        elif pending == 'contact_email_get':
            vars['contact_data'] = clone(data)
            address = data.get('ibanEmail')
            vars['registered_email'] = address if isinstance(address, str) and address.strip() and data.get('communicationType') != 'Phone' else ''
            prefix = str(vars.pop('reading_prefix', '') or '')
            if vars.get('email_requested') == 'yes':
                vars['email_requested'] = 'no'
                email_setup(prefix)
            elif vars.get('registered_email'):
                ask('offer', prefix + 'Ekstrenizi kayıtlı mail adresinize gönderebilirim. İster misiniz?', 'Ekstrenizi kayıtlı adresinize göndermemi ister misiniz?', 'offer:' + str(vars.get('selected_card_number')))
            else:
                menu(prefix)
        elif pending == 'statement_week_get':
            vars['week_data'] = clone(data)
            vars['week_card'] = vars.get('selected_card_number')
            current = data.get('statementWeek')
            day = data.get('statementDay')
            if isinstance(current, bool) or not isinstance(current, int) or current not in (1, 2, 3, 4) or isinstance(day, bool) or not isinstance(day, int):
                raise ValueError('current week shape')
            vars['current_statement_day'] = day
            if known_used():
                menu('Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Bu yıl değişiklik yapıldığı için tekrar değiştiremiyorum. ')
            else:
                text = intro(vars['selected_card'])
                relation = data.get('relationType')
                if relation in ('M', 'C'):
                    other4 = str(data.get('relatedCardNumber') or '')[-4:]
                    text += ' ile ' + ('buna bağlı ' if relation == 'M' else 'bu kartın bağlı olduğu ') + 'sonu ' + digit_speech(other4) + ' ile biten ' + clean(data.get('relatedCardProductName')) + ' kartınız'
                text += ' için hesap kesim haftası her ayın ' + ordinals[current] + ' haftasıdır. Bir sonraki hesap kesim tarihiniz ' + spoken_date(data['nextStatementDate']) + ', son ödeme tarihiniz ' + spoken_date(data['nextLastPayDate']) + '. Hesap kesim tarihinizi değiştirmek ister misiniz?'
                ask('week_start', text, 'Hesap kesim tarihinizi değiştirmek ister misiniz?', 'week_start:' + str(vars.get('selected_card_number')))
        elif pending == 'statement_week_decide':
            if isinstance(data.get('responseCode'), bool) or data.get('responseCode') != 0:
                failure(True)
            else:
                date(data.get('statementDate'))
                date(data.get('statementDueDate'))
                vars['preview_data'] = clone(data)
                vars['preview_key'] = week_key()
                preview_confirmation()
        elif pending == 'statement_week_change':
            if isinstance(data.get('responseCode'), bool) or data.get('responseCode') != 0 or data.get('exitState') != 'OK':
                vars['write_outcome'] = 'unconfirmed'
                failure(True)
            else:
                vars['write_outcome'] = 'confirmed'
                changed = dict(vars.get('changed_years', dict()))
                number = vars.get('selected_card_number')
                changed[number] = today.year
                w = vars['week_data']
                related = w.get('relatedCardNumber') if w.get('relationType') in ('M', 'C') else ''
                if related:
                    changed[related] = today.year
                vars['changed_years'] = changed
                vars['uncertain_changes'] = [x for x in vars.get('uncertain_changes', []) if x not in (number, related)]
                p = vars['preview_data']
                text = intro(vars['selected_card']) + 'ın hesap kesim haftası her ayın ' + ordinals[int(vars['requested_week'])] + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + spoken_date(p['statementDate']) + ', son ödeme tarihiniz ' + spoken_date(p['statementDueDate']) + '. Sizi ana menüye yönlendiriyorum.'
                ask('changed', text, '', 'changed:' + vars['preview_key'])
        elif pending == 'statement_pdf_send':
            if data.get('exitState') == 'DONE':
                vars['write_outcome'] = 'confirmed'
                ask('sent', 'Ekstreniz kayıtlı e-posta adresinize gönderildi. Sizi ana menüye yönlendiriyorum.', '', 'sent:' + str(vars.get('send_attempts')))
            else:
                vars['write_outcome'] = 'unconfirmed'
                failure(False)
        else:
            failure()
    else:
        encoded = vars.pop('speech_event', '')
        try:
            event = json.loads(encoded) if isinstance(encoded, str) and encoded else dict()
        except Exception:
            event = dict()
        e = event if isinstance(event, dict) else dict()
        vars['turn_serial'] = int(vars.get('turn_serial', 0)) + 1
        vars['email_consent'] = 'none'
        vars['week_consent'] = 'none'
        intent = str(e.get('intent') or 'answer')
        answer = str(e.get('answer') or 'unclear')
        stage = str(vars.get('stage') or 'selection')
        raw = str(e.get('raw') or '')
        if e.get('email_requested') is True or intent == 'email':
            vars['email_requested'] = 'yes'
        if e.get('wanted') in ('all', 'minimum', 'due', 'total'):
            vars['wanted'] = e['wanted']
        currency = e.get('currency')
        if currency in names and e.get('currency_raw') and str(e['currency_raw']) in raw:
            vars['wanted_currency'] = currency
        else:
            currency = ''
        if intent != 'silence':
            vars['silences'] = 0
        if intent == 'agent':
            finish('agent', 'Sizi müşteri temsilcimize aktarıyorum.')
        elif intent == 'payment':
            finish('agent', 'Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum.')
        elif intent == 'dispute':
            finish('agent', 'Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum.')
        elif intent == 'third_party':
            finish('ivr_login', 'Güvenlik nedeniyle yalnızca kendi kartlarınız için yardımcı olabilirim. Kart sahibinin kimlik doğrulaması için sizi giriş adımına yönlendiriyorum.')
        elif intent == 'non_turkish':
            finish('main_menu', 'Sizi ana menüye aktarıyorum.')
        elif intent == 'silence':
            vars['silences'] = int(vars.get('silences', 0)) + 1
            if vars['silences'] >= 3:
                finish('closed_silence', 'Sesinizi alamadığım için görüşmeyi sonlandırıyorum.')
            else:
                vars['say'] = vars.get('short_question') or 'Sesinizi alabilir miyim?'
                vars['route'] = 'listen'
        elif intent == 'repeat':
            vars['say'] = vars.get('last_question') or vars.get('last_reading') or 'Ekstre borcunuzla ilgili devam edelim.'
            vars['route'] = 'listen'
        elif intent == 'angry' or e.get('angry') is True:
            count = int(vars.get('calming_replies', 0))
            if count >= 3:
                finish('agent', 'Sizi müşteri temsilcimize aktarıyorum.')
            else:
                vars['calming_replies'] = count + 1
                vars['say'] = 'Sizi anlıyorum, yardımcı olmaya çalışıyorum. ' + str(vars.get('short_question') or '')
                vars['route'] = 'listen'
        elif intent in ('injection', 'volunteered_secret'):
            prefix = 'Lütfen şifre veya tek kullanımlık kod paylaşmayın. ' if intent == 'volunteered_secret' else ''
            fail_try(prefix + str(vars.get('short_question') or 'Ekstre borcunuzla ilgili devam edelim.'))
        elif stage == 'out_of_scope':
            if answer == 'yes':
                menu()
            elif answer == 'no':
                saved = vars.get('resume_state', dict())
                for key in ('stage', 'question_key', 'attempts', 'last_question', 'short_question'):
                    vars[key] = saved.get(key, '' if key != 'attempts' else 0)
                vars['say'] = vars.get('last_question') or 'Ekstre borcunuzla ilgili devam edelim.'
                vars['route'] = 'listen'
            else:
                fail_try('Sizi ana menüye aktarmamı ister misiniz?')
        elif intent == 'out_of_scope':
            vars['resume_state'] = dict((key, vars.get(key)) for key in ('stage', 'question_key', 'attempts', 'last_question', 'short_question'))
            ask('out_of_scope', 'Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?', 'Sizi ana menüye aktarmamı ister misiniz?')
        elif intent in ('switch_transaction', 'done'):
            menu()
        elif e.get('invalid_registered_address') is True:
            menu('Bu görüşmede kayıtlı e-posta adresinizi değiştiremiyorum; ekstrenizi göndermeyeceğim. ')
        elif e.get('other_address') is True or e.get('paper_or_sms') is True or e.get('date_kind') == 'earlier':
            menu('Yalnızca son kesilmiş ekstrenizi bankamızda kayıtlı e-posta adresinize gönderebilirim. ')
        elif stage == 'changed':
            if intent == 'undo':
                menu('Değişiklik tamamlandı; bu görüşmede geri alamıyorum. ')
            elif intent == 'effective_date':
                menu('Yeni hesap kesim tarihiniz ' + spoken_date(vars['preview_data']['statementDate']) + '. ')
            elif intent == 'week':
                start_week()
            else:
                menu()
        elif stage == 'sent':
            if intent in ('resend', 'email') and int(vars.get('send_attempts', 0)) < 3:
                vars['email_requested'] = 'no'
                email_setup()
            else:
                menu()
        elif intent == 'week' and stage not in ('week_start', 'week_choice', 'week_confirm'):
            start_week()
        elif stage in ('selection', 'last4', 'last6', 'full_number') or intent == 'other_card':
            if intent == 'other_card' and stage not in ('selection', 'last4', 'last6', 'full_number'):
                selection(fresh=True)
                stage = 'selection'
            candidates = vars.get('candidates') or eligible()
            name = norm(e.get('card_name')) if e.get('card_name_raw') and str(e['card_name_raw']) in raw else ''
            digits = str(e.get('digits') or '')
            evidence = str(e.get('digits_raw') or '')
            if not evidence or evidence not in raw or not re.fullmatch(r'[0-9]{4}|[0-9]{6}|[0-9]{16}', digits):
                digits = ''
            handled = False
            if e.get('all_cards') is True:
                fail_try('Kartlarınızı birer birer sorgulayabilirim. Hangi kartınızı seçmek istersiniz?')
                handled = True
            elif e.get('no_digits') is True:
                vars['stage'] = 'selection'
                vars['candidates'] = clone(eligible())
                fail_try('Kartınızın adını söyleyebilir misiniz?')
                handled = True
            if not handled and name:
                matches = [c for c in eligible() if norm(c.get('productName')) == name]
                if not matches:
                    matches = [c for c in eligible() if name in norm(c.get('productName'))]
                if not matches:
                    all_names = list(dict.fromkeys(clean(c.get('productName')) for c in eligible() if c.get('productName')))
                    fail_try('Bu ad altında uygun kartınız bulunmuyor. ' + (', '.join(all_names) + '. ' if all_names else '') + 'Hangi kartınızı seçmek istersiniz?')
                    handled = True
                else:
                    candidates = matches
                    vars['candidates'] = clone(matches)
            if not handled and digits:
                if len(digits) == 4:
                    matches = [c for c in candidates if c.get('cardNumberLast4') == digits]
                else:
                    known = [c for c in candidates if re.fullmatch(r'[0-9]{16}', str(c.get('cardNumber') or ''))]
                    if len(known) != len(candidates):
                        vars['stage'] = 'selection'
                        vars['candidates'] = clone(eligible())
                        fail_try('Bu kartları mevcut kart bilgisiyle güvenli biçimde ayırt edemiyorum. Farklı bir kart adı söyleyebilir misiniz?')
                        handled = True
                        matches = []
                    else:
                        matches = [c for c in known if c['cardNumber'].endswith(digits)]
                if not handled:
                    if len(matches) == 1:
                        select(matches[0])
                    elif not matches:
                        fail_try('Bu bilgilerle uygun kartınızı bulamadım. Kart adını veya sorulan haneleri tekrar söyler misiniz?')
                    elif len(digits) == 4:
                        vars['candidates'] = clone(matches)
                        if any(not re.fullmatch(r'[0-9]{16}', str(c.get('cardNumber') or '')) for c in matches):
                            vars['stage'] = 'selection'
                            vars['candidates'] = clone(eligible())
                            fail_try('Bu kartları mevcut kart bilgisiyle güvenli biçimde ayırt edemiyorum. Farklı bir kart adı söyleyebilir misiniz?')
                        else:
                            ask('last6', 'Son dört hanesi ' + digit_speech(digits) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?', 'Kartınızın son altı hanesini söyler misiniz?', 'last6:' + json.dumps([c['cardNumber'] for c in matches]))
                    elif len(digits) == 6:
                        vars['candidates'] = clone(matches)
                        ask('full_number', 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?', 'Kart numaranızı söyler misiniz?', 'full:' + json.dumps([c['cardNumber'] for c in matches]))
                    else:
                        fail_try('Kartı ayırt edemedim. Farklı bir kart seçebilir misiniz?')
                handled = True
            if not handled:
                if name and len(candidates) == 1:
                    select(candidates[0])
                elif name and len(candidates) > 1:
                    card_names = list(dict.fromkeys(clean(c.get('productName')) for c in candidates))
                    key = 'last4:' + json.dumps([c['cardNumber'] for c in candidates])
                    if len(card_names) == 1 and vars.get('question_key') != key:
                        ask('last4', card_names[0] + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?', 'Kartınızın son dört hanesini söyler misiniz?', key)
                    else:
                        fail_try(('Bu tanıma uyan kartlarınız: ' + ', '.join(card_names) + '. ' if len(card_names) > 1 else '') + 'Kart adını veya sorulan haneleri söyler misiniz?')
                else:
                    fail_try('Bir kartı seçmem gerekiyor. Kart adını veya sorulan haneleri söyler misiniz?')
        elif stage in ('week_choice', 'week_confirm') and (e.get('week') or e.get('date_kind') in ('date', 'ambiguous')):
            week = str(e.get('week') or '')
            if week in ('1', '2', '3', '4') and e.get('week_raw') and str(e['week_raw']) in raw and e.get('date_kind', 'none') == 'none':
                if int(week) == vars['week_data']['statementWeek']:
                    menu('Hesap kesim haftanız zaten bu hafta; değişiklik gerekmiyor. ')
                else:
                    vars['requested_week'] = week
                    queue('statement_week_decide')
            else:
                options = [ordinals[w] for w in (1, 2, 3, 4) if w != vars['week_data']['statementWeek']]
                fail_try('Bir gün veya tarih yerine yalnızca ' + ', '.join(options) + ' haftalarından birini seçebilirsiniz. Hangi haftayı tercih edersiniz?')
        elif stage == 'week_start':
            if answer == 'yes':
                week_options()
            elif answer == 'no':
                menu()
            else:
                fail_try('Hesap kesim tarihinizi değiştirmek ister misiniz?')
        elif stage == 'week_choice':
            fail_try(str(vars.get('short_question') or 'Hangi haftayı tercih edersiniz?'))
        elif stage == 'week_confirm':
            if answer == 'yes' and raw:
                if known_used():
                    menu('Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. ')
                elif vars.get('preview_key') == week_key() and vars.get('week_confirm_key') == week_key():
                    vars['week_consent'] = 'clear_yes'
                    vars['consent_serial'] = vars['turn_serial']
                    queue('statement_week_change')
                else:
                    week_options()
            elif answer == 'no':
                menu()
            else:
                fail_try('Belirtilen yeni tarihleri ve varsa diğer kartınıza etkisini açıkça onaylıyor musunuz?')
        elif stage in ('email_confirm', 'email_currency', 'offer') and e.get('date_kind') == 'ambiguous':
            fail_try('Yalnızca son kesilmiş ekstrenizi gönderebilirim. Son kesilmiş ekstrenizi mi istiyorsunuz?')
        elif stage in ('email_confirm', 'email_currency', 'offer') and e.get('date_kind') == 'date' and e.get('date_value') != vars.get('balance_data', dict()).get('statementDate'):
            menu('Yalnızca son kesilmiş ekstrenizi gönderebilirim. ')
        elif stage == 'email_currency':
            if currency in names:
                vars['send_currency'] = currency
                email_setup()
            else:
                fail_try('Türk Lirası, Dolar, Euro veya İngiliz Sterlini ekstrenizden hangisini istersiniz?')
        elif stage == 'email_confirm':
            if currency and currency != vars.get('send_currency'):
                vars['send_currency'] = currency
                email_setup()
            elif answer == 'yes' and raw:
                key = json.dumps([vars.get('selected_card_number'), vars.get('issued_statement_date'), vars.get('send_currency'), vars.get('registered_email')], ensure_ascii=False)
                if key == vars.get('email_confirm_key'):
                    vars['email_consent'] = 'clear_yes'
                    vars['consent_serial'] = vars['turn_serial']
                    queue('statement_pdf_send')
                else:
                    email_setup()
            elif answer == 'no':
                menu()
            else:
                fail_try('Belirtilen ekstrenizi kayıtlı adresinize göndermemi açıkça onaylıyor musunuz?')
        elif intent == 'email':
            vars['email_requested'] = 'yes'
            queue('contact_email_get')
        elif e.get('wanted') in ('due', 'minimum', 'total') and vars.get('balance_card') == vars.get('selected_card_number'):
            offer(reading(vars['balance_data']) + ' ')
        elif intent == 'interrupt':
            offer()
        elif stage == 'another':
            if answer == 'yes':
                vars['wanted'] = 'all'
                vars['wanted_currency'] = ''
                selection(fresh=True)
            elif answer == 'no':
                offer()
            else:
                fail_try('Başka bir kartınızın borcunu öğrenmek ister misiniz?')
        elif stage == 'offer':
            if answer == 'yes':
                vars['email_requested'] = 'no'
                email_setup()
            elif answer == 'no':
                menu()
            else:
                fail_try('Ekstrenizi kayıtlı e-posta adresinize göndermemi ister misiniz?')
        else:
            fail_try(str(vars.get('short_question') or 'Nasıl devam etmek istersiniz?'))
except Exception:
    vars['route'] = 'boundary'
    vars['boundary_intent'] = 'agent'
    vars['email_consent'] = 'none'
    vars['week_consent'] = 'none'
    vars['say'] = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
